function adminApi(method, path, body) {
    const token = (node.credentials && node.credentials.adminToken) || '';
    const hdrs  = token ? { 'Authorization': 'Bearer ' + token } : {};
    return httpRequest(method, 'localhost', adminPort, path, hdrs, body);
}

